     1→/* ============================================
     2→   DESIGN SYSTEM TOKENS V3 - Neo-Brutalist
     3→   Light/Dark Mode × 12 Palettes
     4→   ============================================ */
     5→
     6→/* ============================================
     7→   FALLBACK - Palette par défaut (AVANT les palettes)
     8→   ============================================ */
     9→:root {
    10→  --palette-accent: #FF3300;
    11→  --palette-accent-rgb: 255, 51, 0;
    12→  --palette-accent-hover: #E62E00;
    13→}
    14→
    15→/* ============================================
    16→   PALETTES DE COULEURS (12 thèmes)
    17→   Définissent UNIQUEMENT l'accent
    18→   ============================================ */
    19→
    20→/* NEONS VIFS (6) */
    21→[data-palette="orange"] {
    22→  --palette-accent: #FF3300;
    23→  --palette-accent-rgb: 255, 51, 0;
    24→  --palette-accent-hover: #E62E00;
    25→}
    26→
    27→[data-palette="cyan"] {
    28→  --palette-accent: #00F0FF;
    29→  --palette-accent-rgb: 0, 240, 255;
    30→  --palette-accent-hover: #00D4E0;
    31→}
    32→
    33→[data-palette="magenta"] {
    34→  --palette-accent: #FF006E;
    35→  --palette-accent-rgb: 255, 0, 110;
    36→  --palette-accent-hover: #E00062;
    37→}
    38→
    39→[data-palette="lime"] {
    40→  --palette-accent: #D5FF0A;
    41→  --palette-accent-rgb: 213, 255, 10;
    42→  --palette-accent-hover: #C2E600;
    43→}
    44→
    45→[data-palette="purple"] {
    46→  --palette-accent: #8B5CF6;
    47→  --palette-accent-rgb: 139, 92, 246;
    48→  --palette-accent-hover: #7C4FE0;
    49→}
    50→
    51→[data-palette="pink"] {
    52→  --palette-accent: #FF69B4;
    53→  --palette-accent-rgb: 255, 105, 180;
    54→  --palette-accent-hover: #FF5AA0;
    55→}
    56→
    57→/* TONS SOBRES (6) */
    58→[data-palette="slate"] {
    59→  --palette-accent: #64748B;
    60→  --palette-accent-rgb: 100, 116, 139;
    61→  --palette-accent-hover: #475569;
    62→}
    63→
    64→[data-palette="stone"] {
    65→  --palette-accent: #78716C;
    66→  --palette-accent-rgb: 120, 113, 108;
    67→  --palette-accent-hover: #57534E;
    68→}
    69→
    70→[data-palette="indigo"] {
    71→  --palette-accent: #4F46E5;
    72→  --palette-accent-rgb: 79, 70, 229;
    73→  --palette-accent-hover: #4338CA;
    74→}
    75→
    76→[data-palette="teal"] {
    77→  --palette-accent: #14B8A6;
    78→  --palette-accent-rgb: 20, 184, 166;
    79→  --palette-accent-hover: #0D9488;
    80→}
    81→
    82→[data-palette="ocean"] {
    83→  --palette-accent: #0EA5E9;
    84→  --palette-accent-rgb: 14, 165, 233;
    85→  --palette-accent-hover: #0284C7;
    86→}
    87→
    88→[data-palette="charcoal"] {
    89→  --palette-accent: #374151;
    90→  --palette-accent-rgb: 55, 65, 81;
    91→  --palette-accent-hover: #1F2937;
    92→}
    93→
    94→/* ============================================
    95→   MODE LIGHT (défaut) - Fond clair, texte noir
    96→   ============================================ */
    97→:root,
    98→.light {
    99→  /* Neo-Brutalist Core */
   100→  --neo-bg: #FAFAFA;
   101→  --neo-bg-alt: #F0F0F0;
   102→  --neo-text: #000000;
   103→  --neo-text-inverse: #FFFFFF;
   104→  --neo-border: #000000;
   105→  --neo-shadow: #000000;
   106→  --neo-surface: #FFFFFF;
   107→  --neo-surface-hover: #F5F5F5;
   108→
   109→  /* Accent hérite de la palette */
   110→  --neo-accent: var(--palette-accent);
   111→  --neo-accent-rgb: var(--palette-accent-rgb);
   112→  --neo-accent-hover: var(--palette-accent-hover);
   113→
   114→  /* Sections contrastées */
   115→  --neo-contrast-bg: #1a1a1a;
   116→  --neo-contrast-text: #FFFFFF;
   117→  --neo-contrast-text-muted: rgba(255, 255, 255, 0.6);
   118→  --neo-contrast-border: rgba(255, 255, 255, 0.2);
   119→}
   120→
   121→/* ============================================
   122→   MODE DARK - Fond noir pur, texte blanc
   123→   ============================================ */
   124→.dark {
   125→  /* Neo-Brutalist Core */
   126→  --neo-bg: #0F0F0F;
   127→  --neo-bg-alt: #1A1A1A;
   128→  --neo-text: #FFFFFF;
   129→  --neo-text-inverse: #000000;
   130→  --neo-border: #FFFFFF;
   131→  --neo-shadow: #FFFFFF;
   132→  --neo-surface: #1F1F1F;
   133→  --neo-surface-hover: #2A2A2A;
   134→
   135→  /* Accent hérite de la palette */
   136→  --neo-accent: var(--palette-accent);
   137→  --neo-accent-rgb: var(--palette-accent-rgb);
   138→  --neo-accent-hover: var(--palette-accent-hover);
   139→
   140→  /* Sections contrastées (inversées en dark) */
   141→  --neo-contrast-bg: #FAFAFA;
   142→  --neo-contrast-text: #000000;
   143→  --neo-contrast-text-muted: rgba(0, 0, 0, 0.6);
   144→  --neo-contrast-border: rgba(0, 0, 0, 0.2);
   145→}
   146→
   147→/* ============================================
   148→   LEGACY TOKENS (compatibilité)
   149→   ============================================ */
   150→:root {
   151→  /* ===== COLOR PALETTE ===== */
   152→
   153→  /* Primary - Neon Yellow */
   154→  --color-primary: #D5FF0A;
   155→  --color-primary-rgb: 213, 255, 10;
   156→  --color-primary-50: #FDFFF0;
   157→  --color-primary-100: #F9FFD6;
   158→  --color-primary-200: #F2FFAB;
   159→  --color-primary-300: #E8FF75;
   160→  --color-primary-400: #D5FF0A;
   161→  --color-primary-500: #C2E600;
   162→  --color-primary-600: #9AB800;
   163→  --color-primary-700: #748A00;
   164→  --color-primary-800: #566900;
   165→  --color-primary-900: #2B3400;
   166→
   167→  /* Accent Colors */
   168→  --color-green: #5CE462;
   169→  --color-green-rgb: 92, 228, 98;
   170→  --color-emerald: #00C18B;
   171→  --color-emerald-rgb: 0, 193, 139;
   172→  --color-teal: #009998;
   173→  --color-teal-rgb: 0, 153, 152;
   174→  --color-ocean: #006F84;
   175→  --color-ocean-rgb: 0, 111, 132;
   176→  --color-slate: #2F4858;
   177→  --color-slate-rgb: 47, 72, 88;
   178→
   179→  /* Neutrals - Dark scale */
   180→  --color-neutral-950: #09090b;
   181→  --color-neutral-925: #121214;
   182→  --color-neutral-900: #18181b;
   183→  --color-neutral-850: #1f1f23;
   184→  --color-neutral-800: #27272a;
   185→  --color-neutral-700: #3f3f46;
   186→  --color-neutral-600: #52525b;
   187→  --color-neutral-500: #71717a;
   188→  --color-neutral-400: #a1a1aa;
   189→  --color-neutral-300: #d4d4d8;
   190→  --color-neutral-200: #e4e4e7;
   191→  --color-neutral-100: #f4f4f5;
   192→  --color-neutral-50: #fafafa;
   193→
   194→  /* RGB values for dynamic opacity */
   195→  --color-neutral-950-rgb: 9, 9, 11;
   196→  --color-neutral-900-rgb: 24, 24, 27;
   197→  --color-neutral-850-rgb: 31, 31, 35;
   198→  --color-neutral-800-rgb: 39, 39, 42;
   199→  --color-neutral-100-rgb: 244, 244, 245;
   200→  --color-neutral-50-rgb: 250, 250, 250;
   201→  --color-white-rgb: 255, 255, 255;
   202→  --color-black-rgb: 0, 0, 0;
   203→
   204→  /* Indigo for light mode accent */
   205→  --color-indigo: #4f46e5;
   206→  --color-indigo-rgb: 79, 70, 229;
   207→  --color-indigo-hover: #4338ca;
   208→  --color-indigo-light: #6366f1;
   209→
   210→  /* Semantic Colors */
   211→  --color-success: #5CE462;
   212→  --color-warning: #FBBF24;
   213→  --color-error: #EF4444;
   214→  --color-info: #009998;
   215→
   216→  /* ===== SPACING SCALE ===== */
   217→  --space-0: 0;
   218→  --space-px: 1px;
   219→  --space-0-5: 0.125rem;   /* 2px */
   220→  --space-1: 0.25rem;      /* 4px */
   221→  --space-1-5: 0.375rem;   /* 6px */
   222→  --space-2: 0.5rem;       /* 8px */
   223→  --space-2-5: 0.625rem;   /* 10px */
   224→  --space-3: 0.75rem;      /* 12px */
   225→  --space-3-5: 0.875rem;   /* 14px */
   226→  --space-4: 1rem;         /* 16px */
   227→  --space-5: 1.25rem;      /* 20px */
   228→  --space-6: 1.5rem;       /* 24px */
   229→  --space-7: 1.75rem;      /* 28px */
   230→  --space-8: 2rem;         /* 32px */
   231→  --space-9: 2.25rem;      /* 36px */
   232→  --space-10: 2.5rem;      /* 40px */
   233→  --space-12: 3rem;        /* 48px */
   234→  --space-14: 3.5rem;      /* 56px */
   235→  --space-16: 4rem;        /* 64px */
   236→  --space-20: 5rem;        /* 80px */
   237→  --space-24: 6rem;        /* 96px */
   238→  --space-32: 8rem;        /* 128px */
   239→
   240→  /* ===== BORDER RADIUS ===== */
   241→  --radius-none: 0;
   242→  --radius-sm: 0.25rem;    /* 4px */
   243→  --radius-md: 0.5rem;     /* 8px */
   244→  --radius-lg: 0.75rem;    /* 12px */
   245→  --radius-xl: 1rem;       /* 16px */
   246→  --radius-2xl: 1.5rem;    /* 24px */
   247→  --radius-3xl: 2rem;      /* 32px */
   248→  --radius-full: 9999px;
   249→
   250→  /* ===== SHADOWS ===== */
   251→  --shadow-xs: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
   252→  --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.5), 0 1px 2px -1px rgba(0, 0, 0, 0.5);
   253→  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.5), 0 2px 4px -2px rgba(0, 0, 0, 0.5);
   254→  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.5), 0 4px 6px -4px rgba(0, 0, 0, 0.5);
   255→  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
   256→  --shadow-2xl: 0 25px 50px -12px rgba(0, 0, 0, 0.7);
   257→  --shadow-inner: inset 0 2px 4px 0 rgba(0, 0, 0, 0.3);
   258→
   259→  /* Glow Shadows - Primary (Neon Yellow) */
   260→  --glow-primary-sm: 0 0 10px -2px rgba(213, 255, 10, 0.4);
   261→  --glow-primary-md: 0 0 20px -4px rgba(213, 255, 10, 0.5);
   262→  --glow-primary-lg: 0 0 30px -6px rgba(213, 255, 10, 0.6);
   263→  --glow-primary-xl: 0 0 50px -10px rgba(213, 255, 10, 0.5);
   264→  --glow-primary-intense: 0 0 40px rgba(213, 255, 10, 0.8);
   265→
   266→  /* Glow Shadows - Green */
   267→  --glow-green-sm: 0 0 10px -2px rgba(92, 228, 98, 0.4);
   268→  --glow-green-md: 0 0 20px -4px rgba(92, 228, 98, 0.5);
   269→  --glow-green-lg: 0 0 30px -6px rgba(92, 228, 98, 0.6);
   270→
   271→  /* Glow Shadows - Emerald */
   272→  --glow-emerald-sm: 0 0 10px -2px rgba(0, 193, 139, 0.4);
   273→  --glow-emerald-md: 0 0 20px -4px rgba(0, 193, 139, 0.5);
   274→  --glow-emerald-lg: 0 0 30px -6px rgba(0, 193, 139, 0.6);
   275→
   276→  /* Glow Shadows - Teal */
   277→  --glow-teal-sm: 0 0 10px -2px rgba(0, 153, 152, 0.4);
   278→  --glow-teal-md: 0 0 20px -4px rgba(0, 153, 152, 0.5);
   279→  --glow-teal-lg: 0 0 30px -6px rgba(0, 153, 152, 0.6);
   280→
   281→  /* Glow Shadows - Ocean */
   282→  --glow-ocean-sm: 0 0 10px -2px rgba(0, 111, 132, 0.4);
   283→  --glow-ocean-md: 0 0 20px -4px rgba(0, 111, 132, 0.5);
   284→  --glow-ocean-lg: 0 0 30px -6px rgba(0, 111, 132, 0.6);
   285→
   286→  /* ===== TYPOGRAPHY ===== */
   287→  --font-sans: var(--font-inter), system-ui, -apple-system, sans-serif;
   288→  --font-display: var(--font-montserrat), system-ui, -apple-system, sans-serif;
   289→  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
   290→
   291→  /* Font Sizes */
   292→  --text-xs: 0.75rem;      /* 12px */
   293→  --text-sm: 0.875rem;     /* 14px */
   294→  --text-base: 1rem;       /* 16px */
   295→  --text-lg: 1.125rem;     /* 18px */
   296→  --text-xl: 1.25rem;      /* 20px */
   297→  --text-2xl: 1.5rem;      /* 24px */
   298→  --text-3xl: 1.875rem;    /* 30px */
   299→  --text-4xl: 2.25rem;     /* 36px */
   300→  --text-5xl: 3rem;        /* 48px */
   301→  --text-6xl: 3.75rem;     /* 60px */
   302→  --text-7xl: 4.5rem;      /* 72px */
   303→  --text-8xl: 6rem;        /* 96px */
   304→
   305→  /* Line Heights */
   306→  --leading-none: 1;
   307→  --leading-tight: 1.25;
   308→  --leading-snug: 1.375;
   309→  --leading-normal: 1.5;
   310→  --leading-relaxed: 1.625;
   311→  --leading-loose: 2;
   312→
   313→  /* Letter Spacing */
   314→  --tracking-tighter: -0.05em;
   315→  --tracking-tight: -0.025em;
   316→  --tracking-normal: 0;
   317→  --tracking-wide: 0.025em;
   318→  --tracking-wider: 0.05em;
   319→  --tracking-widest: 0.1em;
   320→
   321→  /* ===== TRANSITIONS ===== */
   322→  --duration-instant: 50ms;
   323→  --duration-fast: 150ms;
   324→  --duration-normal: 300ms;
   325→  --duration-slow: 500ms;
   326→  --duration-slower: 700ms;
   327→  --duration-slowest: 1000ms;
   328→
   329→  --ease-linear: linear;
   330→  --ease-in: cubic-bezier(0.4, 0, 1, 1);
   331→  --ease-out: cubic-bezier(0, 0, 0.2, 1);
   332→  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
   333→  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
   334→  --ease-bounce: cubic-bezier(0.68, -0.6, 0.32, 1.6);
   335→
   336→  /* ===== Z-INDEX SCALE ===== */
   337→  --z-behind: -1;
   338→  --z-base: 0;
   339→  --z-dropdown: 10;
   340→  --z-sticky: 20;
   341→  --z-fixed: 30;
   342→  --z-modal-backdrop: 40;
   343→  --z-modal: 50;
   344→  --z-popover: 60;
   345→  --z-tooltip: 70;
   346→  --z-toast: 80;
   347→
   348→  /* ===== GRADIENTS ===== */
   349→  --gradient-brand: linear-gradient(135deg, #D5FF0A 0%, #5CE462 25%, #00C18B 50%, #009998 75%, #006F84 100%);
   350→  --gradient-brand-short: linear-gradient(135deg, #D5FF0A 0%, #00C18B 100%);
   351→  --gradient-primary: linear-gradient(135deg, #D5FF0A 0%, #5CE462 100%);
   352→  --gradient-primary-teal: linear-gradient(135deg, #D5FF0A 0%, #009998 100%);
   353→  --gradient-teal: linear-gradient(135deg, #00C18B 0%, #006F84 100%);
   354→  --gradient-ocean: linear-gradient(135deg, #009998 0%, #2F4858 100%);
   355→  --gradient-surface: linear-gradient(180deg, #18181b 0%, #09090b 100%);
   356→
   357→  /* Glow Gradients (radial) */
   358→  --gradient-glow-primary: radial-gradient(ellipse 80% 50% at 50% -20%, rgba(213, 255, 10, 0.15), transparent);
   359→  --gradient-glow-teal: radial-gradient(ellipse 80% 50% at 50% -20%, rgba(0, 193, 139, 0.12), transparent);
   360→  --gradient-glow-center: radial-gradient(ellipse 50% 50% at 50% 50%, rgba(213, 255, 10, 0.08), transparent);
   361→}
   362→
   363→/* ===== LEGACY THEME VARIABLES ===== */
   364→/* Ces variables sont pour compatibilité avec l'ancien thème */
   365→.dark {
   366→  --background: var(--color-neutral-950);
   367→  --background-rgb: 9, 9, 11;
   368→  --foreground: var(--color-neutral-50);
   369→  --foreground-rgb: 250, 250, 250;
   370→
   371→  --surface: var(--color-neutral-900);
   372→  --surface-elevated: var(--color-neutral-850);
   373→  --surface-hover: var(--color-neutral-800);
   374→
   375→  --border: var(--color-neutral-800);
   376→  --border-subtle: var(--color-neutral-850);
   377→  --border-strong: var(--color-neutral-700);
   378→
   379→  --text-primary: var(--color-neutral-50);
   380→  --text-secondary: var(--color-neutral-400);
   381→  --text-muted: var(--color-neutral-500);
   382→  --text-inverse: var(--color-neutral-950);
   383→
   384→  --accent: var(--color-primary);
   385→  --accent-hover: var(--color-primary-300);
   386→  --accent-muted: rgba(213, 255, 10, 0.15);
   387→  --accent-glow: rgba(213, 255, 10, 0.4);
   388→
   389→  /* ===== GLASS VARIABLES (Dark) ===== */
   390→  --glass-bg: rgba(24, 24, 27, 0.6);
   391→  --glass-bg-subtle: rgba(24, 24, 27, 0.4);
   392→  --glass-bg-strong: rgba(24, 24, 27, 0.8);
   393→  --glass-border: rgba(255, 255, 255, 0.1);
   394→  --glass-border-subtle: rgba(255, 255, 255, 0.05);
   395→  --glass-border-strong: rgba(255, 255, 255, 0.15);
   396→  --glass-hover: rgba(255, 255, 255, 0.05);
   397→  --glass-active: rgba(255, 255, 255, 0.08);
   398→
   399→  /* ===== OVERLAY VARIABLES (Dark) ===== */
   400→  --overlay-bg: rgba(9, 9, 11, 0.8);
   401→  --overlay-bg-strong: rgba(9, 9, 11, 0.9);
   402→
   403→  /* ===== SHADOW COLOR (Dark) ===== */
   404→  --shadow-color: rgba(0, 0, 0, 0.5);
   405→  --shadow-color-strong: rgba(0, 0, 0, 0.7);
   406→}
   407→
   408→.light {
   409→  --background: var(--color-neutral-50);
   410→  --background-rgb: 250, 250, 250;
   411→  --foreground: var(--color-neutral-950);
   412→  --foreground-rgb: 9, 9, 11;
   413→
   414→  --surface: var(--color-neutral-100);
   415→  --surface-elevated: white;
   416→  --surface-hover: var(--color-neutral-200);
   417→
   418→  --border: var(--color-neutral-200);
   419→  --border-subtle: var(--color-neutral-100);
   420→  --border-strong: var(--color-neutral-300);
   421→
   422→  --text-primary: var(--color-neutral-950);
   423→  --text-secondary: var(--color-neutral-600);
   424→  --text-muted: var(--color-neutral-600);
   425→  --text-inverse: var(--color-neutral-50);
   426→
   427→  /* ===== ACCENT INDIGO (Light) ===== */
   428→  --accent: var(--color-indigo);
   429→  --accent-hover: var(--color-indigo-hover);
   430→  --accent-muted: rgba(79, 70, 229, 0.15);
   431→  --accent-glow: rgba(79, 70, 229, 0.4);
   432→
   433→  /* ===== GLASS VARIABLES (Light) ===== */
   434→  --glass-bg: rgba(255, 255, 255, 0.7);
   435→  --glass-bg-subtle: rgba(255, 255, 255, 0.5);
   436→  --glass-bg-strong: rgba(255, 255, 255, 0.85);
   437→  --glass-border: rgba(0, 0, 0, 0.08);
   438→  --glass-border-subtle: rgba(0, 0, 0, 0.04);
   439→  --glass-border-strong: rgba(0, 0, 0, 0.12);
   440→  --glass-hover: rgba(0, 0, 0, 0.03);
   441→  --glass-active: rgba(0, 0, 0, 0.06);
   442→
   443→  /* ===== OVERLAY VARIABLES (Light) ===== */
   444→  --overlay-bg: rgba(0, 0, 0, 0.5);
   445→  --overlay-bg-strong: rgba(0, 0, 0, 0.7);
   446→
   447→  /* ===== SHADOW COLOR (Light) ===== */
   448→  --shadow-color: rgba(0, 0, 0, 0.1);
   449→  --shadow-color-strong: rgba(0, 0, 0, 0.2);
   450→
   451→  /* ===== GLOWS (Light - Indigo based) ===== */
   452→  --glow-primary-sm: 0 0 10px -2px rgba(79, 70, 229, 0.3);
   453→  --glow-primary-md: 0 0 20px -4px rgba(79, 70, 229, 0.4);
   454→  --glow-primary-lg: 0 0 30px -6px rgba(79, 70, 229, 0.5);
   455→  --glow-primary-xl: 0 0 50px -10px rgba(79, 70, 229, 0.4);
   456→  --glow-primary-intense: 0 0 40px rgba(79, 70, 229, 0.6);
   457→
   458→  /* ===== GRADIENTS (Light) ===== */
